def history_budget_development_seed(*, programme_ordinal: int, unit_ordinal: int) -> bytes:
    if type(programme_ordinal) is not int or not 0 <= programme_ordinal < 3:
        raise ValueError("history scientific seed requires a known numerical programme ordinal")
    if type(unit_ordinal) is not int or not 0 <= unit_ordinal < len(_DEVELOPMENT_SEED_HEX[programme_ordinal]):
        raise ValueError("history development scientific seed requires its complete known unit coordinate")
    return bytes.fromhex(_DEVELOPMENT_SEED_HEX[programme_ordinal][unit_ordinal])


def history_budget_fixed_seed(*, programme_ordinal: int, scientific_role: str, numeric_index: int) -> bytes:
    if type(programme_ordinal) is not int or type(numeric_index) is not int:
        raise ValueError("history fixed scientific seed requires exact numerical coordinates")
    for programme, role, index, seed in _FIXED_SEED_HEX:
        if (programme, role, index) == (programme_ordinal, scientific_role, numeric_index):
            return bytes.fromhex(seed)
    raise ValueError("history fixed scientific seed coordinate is unsupported")


def history_budget_reserved_seed_digests(*, programme_ordinal: int) -> frozenset[str]:
    if type(programme_ordinal) is not int or not 0 <= programme_ordinal < 3:
        raise ValueError("history seed exclusion requires a known numerical programme ordinal")
    return frozenset(_RESERVED_SEED_DIGESTS[programme_ordinal])
